runpy.run_path("ci/generate_chatgpt_webview_v90_resource_posteffect_telemetry_repair.py",run_name="__main__")
ROOT=Path("runtime_probes/chatgpt-webview-stable-probe")
PKG=ROOT/"app/src/main/java/com/homayounisaghar/chatgptwebviewprobe"
ACT=PKG/"OrchestratorDashboardV91Activity.java";CFG=PKG/"TelemetryConfigV91.java"
