man=ROOT/"app/src/main/AndroidManifest.xml";ms=man.read_text();assert ms.count("OrchestratorResourceToolsV90Activity")==1;man.write_text(ms.replace("OrchestratorResourceToolsV90Activity","OrchestratorDashboardV91Activity",1))
grad=ROOT/"app/build.gradle";gs=grad.read_text();assert re.search(r"versionCode\s+91\b",gs);gs=re.sub(r"versionCode\s+91\b","versionCode 92",gs,1);assert "0.88-stable-diag-resource-posteffect-telemetry-repair" in gs;grad.write_text(gs.replace("0.88-stable-diag-resource-posteffect-telemetry-repair","0.89-stable-dashboard-observer-registry",1))
out=ACT.read_text()
for x in ['OrchestratorDashboardV91Activity','BIND CURRENT','REFRESH ALL','AtomicFile','dashboard_registry_v91.json','OBSERVE_ONLY','MAX_BINDINGS=5','FRESH_TTL_MS','RUNNING','QUIET_ASSISTANT_LAST','QUIET_USER_LAST','STALE','UNKNOWN','scanGeneration','activeId','activePath','ROUTE_RECEIPT_CONFIRMED','raw_text_remote",false','raw_path_remote",false','chat_effect_dispatches",0','TelemetryConfigV91','cp-v91-dashboard-observer-registry-v1']:assert x in out,x
